// Ensure an actor is selected
let actor = canvas.tokens.controlled[0]?.actor;
if (!actor) {
    ui.notifications.warn("No actor selected!");
    return;
}

// Filter out the consumables which have a max uses greater than 1
const consumablesToDecrease = actor.items.filter(item => {
    return item.type === 'consumable' && item.system.uses && item.system.uses.max > 1 && item.system.uses.value > 0;
});

// Generate a list of item names to display in the dialog
const itemNames = consumablesToDecrease.map(item => `${item.name} (${item.system.uses.value}/${item.system.uses.max} rounds of cooldown left)`).join("</li><li>");

// Function to decrease the use count of consumable items
async function decreaseUsesForConsumables(items) {
    for (let item of items) {
        // Decrease the item's uses value
        await item.update({'system.uses.value': item.system.uses.value - 1});
        console.log(`Decreased uses for ${item.name}: now ${item.system.uses.value}/${item.system.uses.max}`);
    }
}

// Create the dialog content
const dialogContent = `<p>Do you want to advance the round and count down the cooldowns for the following items?</p><ul><li>${itemNames}</li></ul>`;

// Create the dialog
const proceed = await foundry.applications.api.DialogV2.confirm({
    window: { title: "Advance Round" },
    content: dialogContent,
    yes: { icon: "fas fa-check", label: "Yes", default: false },
    no: { icon: "fas fa-times", label: "No", default: true },
    rejectClose: false
});
if (proceed) {
    console.log("Advancing round and updating consumables.");
    await decreaseUsesForConsumables(consumablesToDecrease);
}
